export interface DiaryEntry {
  id: string;
  dayMonth: string; // Format "MM-DD"
  year: number;
  content: string;
  mood?: string; // Emoji
  lastEdited: number;
}

export type MoodOption = {
  emoji: string;
  label: string;
  color: string;
};

export interface DailyInsight {
  date: string;
  insight: string;
}

// Map of "MM-DD" to Year to Entry
export type DiaryDatabase = Record<string, Record<number, DiaryEntry>>;

export const MOODS: MoodOption[] = [
  { emoji: '☀️', label: 'Sunny', color: 'bg-amber-100 text-amber-600' },
  { emoji: '☁️', label: 'Cloudy', color: 'bg-gray-100 text-gray-600' },
  { emoji: '🌧️', label: 'Rainy', color: 'bg-blue-100 text-blue-600' },
  { emoji: '🌱', label: 'Growing', color: 'bg-green-100 text-green-600' },
  { emoji: '✨', label: 'Inspired', color: 'bg-purple-100 text-purple-600' },
  { emoji: '🍵', label: 'Calm', color: 'bg-teal-100 text-teal-600' },
  { emoji: '🔥', label: 'Active', color: 'bg-orange-100 text-orange-600' },
  { emoji: '🌚', label: 'Tired', color: 'bg-slate-100 text-slate-600' },
];

import { DiaryDatabase, DiaryEntry } from '../types';

const STORAGE_KEY = 'chronolog_data_v1';

const getDB = (): DiaryDatabase => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    console.error("Failed to load diary data", e);
    return {};
  }
};

const saveDB = (db: DiaryDatabase) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
  } catch (e) {
    console.error("Failed to save diary data", e);
  }
};

export const getEntryForDate = (month: number, day: number, year: number): DiaryEntry | null => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  return db[dateKey]?.[year] || null;
};

export const getEntriesForDay = (month: number, day: number): DiaryEntry[] => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  const yearMap = db[dateKey];
  if (!yearMap) return [];
  return Object.values(yearMap).sort((a, b) => b.year - a.year);
};

export const saveEntry = (entry: DiaryEntry): void => {
  const db = getDB();
  const dateKey = entry.dayMonth;

  if (!db[dateKey]) {
    db[dateKey] = {};
  }

  db[dateKey][entry.year] = entry;
  saveDB(db);
};

export const deleteEntry = (month: number, day: number, year: number): void => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  if (db[dateKey] && db[dateKey][year]) {
    delete db[dateKey][year];
    saveDB(db);
  }
};

import { GoogleGenAI } from "@google/genai";
import { DiaryEntry } from '../types';

export const generateTimeCapsuleInsight = async (
  dateStr: string,
  entries: DiaryEntry[]
): Promise<string> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please provide a valid API key.");
  }

  if (entries.length < 2) {
    return "Not enough entries to generate a comparison pattern. Write more to see your growth!";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Sort entries chronologically for the model
  const sortedEntries = [...entries].sort((a, b) => a.year - b.year);

  const entriesText = sortedEntries.map(e => 
    `[${e.year}]: Mood: ${e.mood || 'None'} - Content: "${e.content}"`
  ).join('\n');

  const prompt = `
    You are a gentle, insightful personal diarist assistant.
    The user is looking at their "5-Year Diary" for the date: ${dateStr}.

    Here are their entries from different years on this exact day:
    ${entriesText}

    Please provide a short, warm, and healing reflection (approx 100-150 words).
    Focus on:
    1. Common themes or recurring emotions on this day.
    2. Signs of growth, maturity, or change in perspective.
    3. A gentle encouragement for the future.

    Do not use markdown headers like ##. Just use paragraphs. 
    Tone: Soothing, observant, "Japanese Zakka" style (simple, mindful).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 } // Flash doesn't need high thinking for this
      }
    });

    return response.text || "I couldn't generate an insight at this moment.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The stars are a bit cloudy right now. Please try again later.";
  }
};

