import React, { useState, useEffect, useRef } from 'react';
import { DiaryEntry, MOODS, MoodOption } from '../types';
import * as storageService from '../services/storageService';

interface EntryCardProps {
  dayMonth: string;
  defaultYear: number;
  initialData: DiaryEntry | null;
  onUpdate: () => void;
  isToday: boolean;
}

const EntryCard: React.FC<EntryCardProps> = ({ dayMonth, defaultYear, initialData, onUpdate, isToday }) => {
  const [year, setYear] = useState(defaultYear);
  const [content, setContent] = useState(initialData?.content || '');
  const [mood, setMood] = useState<string | undefined>(initialData?.mood);
  const [isFocused, setIsFocused] = useState(false);
  const [isEditingYear, setIsEditingYear] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [content]);

  // Sync with initialData changes (e.g. when changing date)
  useEffect(() => {
    setYear(defaultYear); // Reset to default slot year when day changes
    if (initialData) {
      setContent(initialData.content);
      setMood(initialData.mood);
      setYear(initialData.year); // If data exists, use its year
    } else {
      setContent('');
      setMood(undefined);
    }
  }, [dayMonth, defaultYear, initialData]);

  const handleSave = () => {
    if (!content.trim()) {
      if (initialData) {
        // If content is cleared, maybe delete? Or just save empty.
        // Let's keep it simple: save empty.
      }
    }

    const entry: DiaryEntry = {
      id: initialData?.id || crypto.randomUUID(),
      dayMonth,
      year,
      content,
      mood,
      lastEdited: Date.now(),
    };

    storageService.saveEntry(entry);
    onUpdate();
  };

  // Debounce save
  useEffect(() => {
    const timer = setTimeout(() => {
      if (content !== (initialData?.content || '') || mood !== initialData?.mood || year !== (initialData?.year || defaultYear)) {
         if (content.trim().length > 0 || mood) {
             handleSave();
         }
      }
    }, 1000);

    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [content, mood, year]);


  return (
    <div 
      className={`
        relative group transition-all duration-300 ease-in-out
        bg-white rounded-xl border border-stone-200 
        ${isFocused ? 'shadow-md ring-1 ring-accent/30 scale-[1.01]' : 'shadow-sm hover:shadow-md'}
        p-5 flex flex-col gap-3
      `}
    >
      {/* Header: Year & Mood */}
      <div className="flex justify-between items-center border-b border-stone-100 pb-2">
        <div className="flex items-center gap-2">
          {isEditingYear ? (
            <input
              type="number"
              value={year}
              onChange={(e) => setYear(parseInt(e.target.value) || year)}
              onBlur={() => setIsEditingYear(false)}
              className="font-serif text-2xl font-bold text-ink w-20 bg-stone-50 rounded px-1 outline-none focus:ring-1 focus:ring-accent"
              autoFocus
            />
          ) : (
            <h3 
              onClick={() => setIsEditingYear(true)}
              className="font-serif text-2xl font-bold text-accent cursor-pointer hover:text-stone-600 transition-colors"
              title="Click to change year"
            >
              {year}
            </h3>
          )}
          <span className="text-xs text-stone-400 font-medium tracking-widest uppercase">
            {initialData ? 'Recorded' : 'Empty'}
          </span>
        </div>

        {/* Mood Selector */}
        <div className="relative">
            <div className="flex gap-1">
                {mood ? (
                    <button 
                        onClick={() => setMood(undefined)}
                        className="text-2xl hover:scale-110 transition-transform"
                    >
                        {mood}
                    </button>
                ) : (
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                        {MOODS.slice(0, 4).map((m) => (
                            <button
                                key={m.label}
                                onClick={() => setMood(m.emoji)}
                                className="text-xl hover:scale-125 transition-transform"
                                title={m.label}
                            >
                                {m.emoji}
                            </button>
                        ))}
                    </div>
                )}
            </div>
        </div>
      </div>

      {/* Input Area */}
      <textarea
        ref={textareaRef}
        value={content}
        onChange={(e) => setContent(e.target.value)}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
        placeholder={`What happened on this day in ${year}?`}
        className="w-full resize-none outline-none bg-transparent text-lg leading-relaxed text-ink placeholder:text-stone-300 min-h-[80px]"
        rows={1}
      />

      {/* Decorative Line (visualizing connection to timeline) */}
      <div className="absolute -left-3 top-8 w-1 h-8 bg-stone-200 rounded-full hidden md:block opacity-50"></div>
    </div>
  );
};

export default EntryCard;

import React from 'react';
import { ChevronLeft, ChevronRight, CalendarIcon } from './Icons';

interface DateNavigatorProps {
  currentDate: Date;
  onDateChange: (date: Date) => void;
}

const DateNavigator: React.FC<DateNavigatorProps> = ({ currentDate, onDateChange }) => {
  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric' }).format(date);
  };

  const changeDay = (days: number) => {
    const newDate = new Date(currentDate);
    newDate.setDate(currentDate.getDate() + days);
    onDateChange(newDate);
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && date.getMonth() === today.getMonth();
  };

  return (
    <div className="sticky top-0 z-10 bg-paper/95 backdrop-blur-sm border-b border-stone-200/60 pb-4 pt-6 px-4 mb-6 shadow-[0_4px_20px_-12px_rgba(0,0,0,0.05)]">
      <div className="max-w-xl mx-auto flex items-center justify-between">

        <button 
          onClick={() => changeDay(-1)}
          className="p-2 rounded-full hover:bg-white hover:shadow-sm text-stone-500 hover:text-ink transition-all"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>

        <div className="flex flex-col items-center">
            <h2 className="font-serif text-3xl font-medium text-ink tracking-tight flex items-center gap-2">
                {formatDate(currentDate)}
            </h2>
            {isToday(currentDate) && (
                <span className="text-xs font-bold text-accent tracking-widest uppercase mt-1">Today</span>
            )}
        </div>

        <button 
          onClick={() => changeDay(1)}
          className="p-2 rounded-full hover:bg-white hover:shadow-sm text-stone-500 hover:text-ink transition-all"
        >
          <ChevronRight className="w-6 h-6" />
        </button>

      </div>

      {/* Decorative timeline circles */}
      <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-1/2 w-2 h-2 bg-accent rounded-full hidden md:block"></div>
    </div>
  );
};

export default DateNavigator;

import React, { useState, useEffect, useMemo } from 'react';
import DateNavigator from './components/DateNavigator';
import EntryCard from './components/EntryCard';
import { Sparkles } from './components/Icons';
import * as storageService from './services/storageService';
import * as geminiService from './services/geminiService';
import { DiaryEntry } from './types';

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  // Base year is the "top" year shown. Defaults to current year.
  const [baseYear, setBaseYear] = useState(new Date().getFullYear());
  const [entries, setEntries] = useState<DiaryEntry[]>([]);
  // Use a refresh trigger to re-fetch data when something changes
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const [isGenerating, setIsGenerating] = useState(false);
  const [insight, setInsight] = useState<string | null>(null);

  const dayMonth = useMemo(() => {
    const m = (currentDate.getMonth() + 1).toString().padStart(2, '0');
    const d = currentDate.getDate().toString().padStart(2, '0');
    return `${m}-${d}`;
  }, [currentDate]);

  // Load entries for current day whenever date or trigger changes
  useEffect(() => {
    const loaded = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
    setEntries(loaded);
    setInsight(null); // Clear insight when changing date
  }, [currentDate, refreshTrigger]);

  const handleUpdate = () => {
    setRefreshTrigger(prev => prev + 1);
  };

  const generateInsight = async () => {
    setIsGenerating(true);
    try {
      // Fetch fresh entries to be sure
      const currentEntries = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
      const result = await geminiService.generateTimeCapsuleInsight(dayMonth, currentEntries);
      setInsight(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  // Generate the list of years to display (Base down to Base-4)
  const displayYears = useMemo(() => {
    return Array.from({ length: 5 }, (_, i) => baseYear - i);
  }, [baseYear]);

  return (
    <div className="h-screen flex flex-col bg-paper relative">
      <DateNavigator currentDate={currentDate} onDateChange={setCurrentDate} />

      <div className="flex-1 overflow-y-auto no-scrollbar pb-20">
        <main className="max-w-2xl mx-auto px-4 w-full flex flex-col gap-6 pt-4">

          {/* Controls for Year Range */}
          <div className="flex justify-end items-center px-1">
             <div className="text-xs text-stone-400 flex gap-2">
                <button onClick={() => setBaseYear(b => b + 1)} className="hover:text-accent underline">Shift Newer</button>
                <span>|</span>
                <button onClick={() => setBaseYear(b => b - 1)} className="hover:text-accent underline">Shift Older</button>
             </div>
          </div>

          {/* Render Cards */}
          {displayYears.map((year) => {
            // Check if we have an entry for this specific year in our loaded entries
            const existingEntry = entries.find(e => e.year === year) || null;

            return (
              <EntryCard
                key={`${dayMonth}-${year}`}
                dayMonth={dayMonth}
                defaultYear={year}
                initialData={existingEntry}
                onUpdate={handleUpdate}
                isToday={
                    currentDate.getDate() === new Date().getDate() && 
                    currentDate.getMonth() === new Date().getMonth() &&
                    year === new Date().getFullYear()
                }
              />
            );
          })}

          {/* AI Insight Section */}
          <div className="mt-8 mb-12">
            {insight ? (
               <div className="bg-gradient-to-br from-stone-50 to-stone-100 rounded-2xl p-6 border border-stone-200 shadow-inner relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-4 opacity-10">
                   <Sparkles className="w-24 h-24 text-accent" />
                 </div>
                 <h3 className="font-serif text-xl font-medium text-accent mb-3 flex items-center gap-2">
                    <Sparkles className="w-5 h-5" />
                    Time Patterns
                 </h3>
                 <p className="text-stone-600 leading-relaxed font-serif whitespace-pre-wrap">{insight}</p>
                 <button onClick={() => setInsight(null)} className="mt-4 text-xs text-stone-400 hover:text-stone-600">Close</button>
               </div>
            ) : (
                entries.length >= 2 && (
                    <div className="flex justify-center">
                        <button
                            onClick={generateInsight}
                            disabled={isGenerating}
                            className={`
                                group relative overflow-hidden
                                bg-white hover:bg-stone-50
                                border border-stone-200 text-stone-500 hover:text-accent
                                px-6 py-3 rounded-full shadow-sm
                                transition-all duration-300
                                flex items-center gap-2 text-sm font-medium tracking-wide
                                ${isGenerating ? 'opacity-70 cursor-wait' : ''}
                            `}
                        >
                            <Sparkles className={`w-4 h-4 ${isGenerating ? 'animate-pulse' : 'group-hover:rotate-12 transition-transform'}`} />
                            {isGenerating ? 'Connecting dots...' : 'Find patterns across years'}
                        </button>
                    </div>
                )
            )}
          </div>
        </main>
      </div>

      {/* Decorative vertical line for desktop */}
      <div className="fixed top-0 bottom-0 left-1/2 -translate-x-1/2 w-px bg-stone-200 -z-0 hidden md:block pointer-events-none opacity-40"></div>
    </div>
  );
};

export default App;

