import React, { useState, useEffect, useRef, useMemo } from 'react';
import { DiaryEntry, MOODS, INSPIRATION_PROMPTS } from '../types';
import * as storageService from '../services/storageService';
import { TrashIcon } from './Icons';

interface EntryCardProps {
  dayMonth: string;
  initialData: DiaryEntry;
  onUpdate: () => void;
  onDelete: (year: number) => void;
}

const EntryCard: React.FC<EntryCardProps> = ({ dayMonth, initialData, onUpdate, onDelete }) => {
  const [year, setYear] = useState(initialData.year);
  const [content, setContent] = useState(initialData.content || '');
  const [mood, setMood] = useState<string | undefined>(initialData.mood);
  const [isFocused, setIsFocused] = useState(false);

  // If the entry has no content yet, allow editing the year by default
  const [isEditingYear, setIsEditingYear] = useState(!initialData.content && !initialData.mood);

  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Pick a random prompt when the component mounts
  const randomPrompt = useMemo(() => {
    return INSPIRATION_PROMPTS[Math.floor(Math.random() * INSPIRATION_PROMPTS.length)];
  }, []);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [content]);

  // Sync with initialData if props change externally
  useEffect(() => {
    setYear(initialData.year);
    setContent(initialData.content);
    setMood(initialData.mood);
  }, [initialData]);

  const handleSave = (newYear: number, newContent: string, newMood: string | undefined) => {
    // If year changed, we might need to delete the old key entry if we were strictly enforcing keys,
    // but here we just update the entry record.
    // NOTE: In a real app, changing year requires handling collision/moving keys.
    // For now, we assume simple update. Logic in storageService needs to handle overwrite.

    // If user changed year, we need to delete the OLD year entry from storage first to avoid duplicates
    if (newYear !== initialData.year) {
        storageService.deleteEntry(
            parseInt(dayMonth.split('-')[0]),
            parseInt(dayMonth.split('-')[1]),
            initialData.year
        );
    }

    const entry: DiaryEntry = {
      id: initialData.id,
      dayMonth,
      year: newYear,
      content: newContent,
      mood: newMood,
      lastEdited: Date.now(),
    };

    storageService.saveEntry(entry);
    onUpdate();
  };

  // Debounce save
  useEffect(() => {
    const timer = setTimeout(() => {
      // Only save if dirty
      if (
        content !== initialData.content || 
        mood !== initialData.mood || 
        year !== initialData.year
      ) {
         handleSave(year, content, mood);
      }
    }, 800);

    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [content, mood, year]);

  const handleDelete = () => {
    if (window.confirm("Delete this memory?")) {
        storageService.deleteEntry(
            parseInt(dayMonth.split('-')[0]),
            parseInt(dayMonth.split('-')[1]),
            year
        );
        onDelete(year);
    }
  };

  return (
    <div 
      className={`
        relative group transition-all duration-500 ease-out
        bg-white rounded-xl border border-stone-200 
        ${isFocused ? 'shadow-lg ring-1 ring-accent/40 scale-[1.01]' : 'shadow-sm hover:shadow-md'}
        p-6 flex flex-col gap-4
      `}
    >
      {/* Header: Year & Mood */}
      <div className="flex justify-between items-start border-b border-stone-100 pb-3">
        <div className="flex flex-col gap-1">
          <div className="flex items-center gap-2">
            {isEditingYear ? (
              <input
                type="number"
                value={year}
                onChange={(e) => setYear(parseInt(e.target.value) || year)}
                onBlur={() => setIsEditingYear(false)}
                className="font-serif text-3xl font-bold text-ink w-24 bg-stone-50 rounded px-1 outline-none focus:ring-1 focus:ring-accent"
                autoFocus
                placeholder="Year"
              />
            ) : (
              <h3 
                onClick={() => setIsEditingYear(true)}
                className="font-serif text-3xl font-bold text-accent cursor-pointer hover:text-stone-600 transition-colors"
                title="Click to edit year"
              >
                {year}
              </h3>
            )}

            {/* Delete button (only visible on hover/focus) */}
            <button 
                onClick={handleDelete}
                className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-stone-300 hover:text-red-400"
                title="Delete entry"
            >
                <TrashIcon className="w-4 h-4" />
            </button>
          </div>

          <span className="text-[10px] text-stone-400 font-medium tracking-widest uppercase ml-1">
            {initialData.lastEdited ? 'Saved' : 'New Entry'}
          </span>
        </div>

        {/* Mood Selector */}
        <div className="relative pt-1">
            <div className="flex gap-1 justify-end">
                {mood ? (
                    <button 
                        onClick={() => setMood(undefined)}
                        className="text-2xl hover:scale-110 transition-transform"
                    >
                        {mood}
                    </button>
                ) : (
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1 flex-wrap justify-end max-w-[150px]">
                        {MOODS.slice(0, 5).map((m) => (
                            <button
                                key={m.label}
                                onClick={() => setMood(m.emoji)}
                                className="text-xl hover:scale-125 transition-transform p-0.5"
                                title={m.label}
                            >
                                {m.emoji}
                            </button>
                        ))}
                    </div>
                )}
            </div>
        </div>
      </div>

      {/* Input Area */}
      <div className="relative">
          <textarea
            ref={textareaRef}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
            placeholder={randomPrompt}
            className="w-full resize-none outline-none bg-transparent text-lg leading-relaxed text-ink placeholder:text-stone-300 placeholder:italic min-h-[80px]"
            rows={2}
          />
      </div>

      {/* Decorative Line */}
      <div className="absolute -left-3 top-8 bottom-8 w-1 bg-gradient-to-b from-stone-200 to-transparent rounded-full hidden md:block opacity-40"></div>
    </div>
  );
};

export default EntryCard;

import React, { useState, useEffect, useMemo } from 'react';
import DateNavigator from './components/DateNavigator';
import EntryCard from './components/EntryCard';
import { Sparkles, PlusIcon } from './components/Icons';
import * as storageService from './services/storageService';
import * as geminiService from './services/geminiService';
import { DiaryEntry } from './types';

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [entries, setEntries] = useState<DiaryEntry[]>([]);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const [isGenerating, setIsGenerating] = useState(false);
  const [insight, setInsight] = useState<string | null>(null);

  const dayMonth = useMemo(() => {
    const m = (currentDate.getMonth() + 1).toString().padStart(2, '0');
    const d = currentDate.getDate().toString().padStart(2, '0');
    return `${m}-${d}`;
  }, [currentDate]);

  // Load entries for current day
  useEffect(() => {
    const loaded = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
    setEntries(loaded);
    setInsight(null);
  }, [currentDate, refreshTrigger]);

  const handleUpdate = () => {
    setRefreshTrigger(prev => prev + 1);
  };

  const handleManualDelete = (yearToDelete: number) => {
     setEntries(prev => prev.filter(e => e.year !== yearToDelete));
     handleUpdate();
  };

  const handleAddEntry = () => {
    // Find a logical year suggestion
    const currentYear = new Date().getFullYear();
    const existingYears = new Set(entries.map(e => e.year));

    let suggestedYear = currentYear;
    // Simple logic: if current year exists, try going back until we find a gap or just add previous
    while (existingYears.has(suggestedYear)) {
        suggestedYear--;
    }

    const newEntry: DiaryEntry = {
        id: crypto.randomUUID(),
        dayMonth,
        year: suggestedYear,
        content: '',
        lastEdited: 0 // 0 marks it as unsaved/new visually in component
    };

    // Add to local state immediately so it renders
    setEntries(prev => [newEntry, ...prev].sort((a, b) => b.year - a.year));
  };

  const generateInsight = async () => {
    setIsGenerating(true);
    try {
      const currentEntries = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
      const result = await geminiService.generateTimeCapsuleInsight(dayMonth, currentEntries);
      setInsight(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-paper relative">
      {/* Header / Nav */}
      <DateNavigator currentDate={currentDate} onDateChange={setCurrentDate} />

      <div className="flex-1 overflow-y-auto no-scrollbar pb-32">
        <main className="max-w-2xl mx-auto px-4 w-full flex flex-col gap-6 pt-4">

          <div className="flex justify-between items-center px-1 mb-2">
             <h2 className="text-sm font-serif text-stone-400 italic">Timeline</h2>
             {/* Dynamic Header Info or Filter could go here */}
          </div>

          {/* Render Cards - Dynamic List */}
          {entries.length === 0 ? (
              <div className="text-center py-20 opacity-40">
                  <p className="font-serif text-xl mb-2">No memories yet.</p>
                  <p className="text-sm">Click the + button to start a ring.</p>
              </div>
          ) : (
              entries.map((entry) => (
                <EntryCard
                    key={`${dayMonth}-${entry.year}-${entry.id}`} // visual key
                    dayMonth={dayMonth}
                    initialData={entry}
                    onUpdate={handleUpdate}
                    onDelete={handleManualDelete}
                />
              ))
          )}

          {/* AI Insight Section */}
          <div className="mt-4 mb-8">
            {insight ? (
               <div className="bg-gradient-to-br from-stone-50 to-stone-100 rounded-2xl p-6 border border-stone-200 shadow-inner relative overflow-hidden animate-in fade-in duration-700">
                 <div className="absolute top-0 right-0 p-4 opacity-10">
                   <Sparkles className="w-24 h-24 text-accent" />
                 </div>
                 <h3 className="font-serif text-xl font-medium text-accent mb-3 flex items-center gap-2">
                    <Sparkles className="w-5 h-5" />
                    Time Patterns
                 </h3>
                 <p className="text-stone-600 leading-relaxed font-serif whitespace-pre-wrap">{insight}</p>
                 <button onClick={() => setInsight(null)} className="mt-4 text-xs text-stone-400 hover:text-stone-600">Close</button>
               </div>
            ) : (
                entries.filter(e => e.content.length > 5).length >= 2 && (
                    <div className="flex justify-center">
                        <button
                            onClick={generateInsight}
                            disabled={isGenerating}
                            className={`
                                group relative overflow-hidden
                                bg-white hover:bg-stone-50
                                border border-stone-200 text-stone-500 hover:text-accent
                                px-6 py-3 rounded-full shadow-sm
                                transition-all duration-300
                                flex items-center gap-2 text-sm font-medium tracking-wide
                                ${isGenerating ? 'opacity-70 cursor-wait' : ''}
                            `}
                        >
                            <Sparkles className={`w-4 h-4 ${isGenerating ? 'animate-pulse' : 'group-hover:rotate-12 transition-transform'}`} />
                            {isGenerating ? 'Connecting dots...' : 'Find patterns across years'}
                        </button>
                    </div>
                )
            )}
          </div>
        </main>
      </div>

      {/* Floating Action Button for Adding Year */}
      <div className="absolute bottom-8 right-6 md:right-1/4 z-20">
        <button
            onClick={handleAddEntry}
            className="bg-accent text-white p-4 rounded-full shadow-lg hover:bg-stone-600 hover:scale-110 active:scale-95 transition-all duration-300 flex items-center justify-center group"
            title="Add a memory for a year"
        >
            <PlusIcon className="w-8 h-8 group-hover:rotate-90 transition-transform" />
        </button>
      </div>

      {/* Decorative vertical line for desktop */}
      <div className="fixed top-0 bottom-0 left-1/2 -translate-x-1/2 w-px bg-stone-200 -z-0 hidden md:block pointer-events-none opacity-40"></div>
    </div>
  );
};

export default App;

