import { DiaryDatabase, DiaryEntry } from '../types';

const STORAGE_KEY = 'chronolog_data_v1';

const getDB = (): DiaryDatabase => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    console.error("Failed to load diary data", e);
    return {};
  }
};

const saveDB = (db: DiaryDatabase) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
  } catch (e) {
    console.error("Failed to save diary data", e);
  }
};

export const getEntryForDate = (month: number, day: number, year: number): DiaryEntry | null => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  return db[dateKey]?.[year] || null;
};

export const getEntriesForDay = (month: number, day: number): DiaryEntry[] => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  const yearMap = db[dateKey];
  if (!yearMap) return [];
  return Object.values(yearMap).sort((a, b) => b.year - a.year);
};

export const saveEntry = (entry: DiaryEntry): void => {
  const db = getDB();
  const dateKey = entry.dayMonth;

  if (!db[dateKey]) {
    db[dateKey] = {};
  }

  db[dateKey][entry.year] = entry;
  saveDB(db);
};

export const deleteEntry = (month: number, day: number, year: number): void => {
  const db = getDB();
  const dateKey = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
  if (db[dateKey] && db[dateKey][year]) {
    delete db[dateKey][year];
    saveDB(db);
  }
};

/**
 * Returns a map of Day -> Count of entries for a specific month.
 * Key: day number (1-31), Value: count of entries across all years.
 */
export const getEntryCountsForMonth = (month: number): Record<number, number> => {
    const db = getDB();
    const result: Record<number, number> = {};
    const monthPrefix = month.toString().padStart(2, '0');

    // Key format is "MM-DD"
    Object.keys(db).forEach(key => {
        const [m, d] = key.split('-');
        if (m === monthPrefix) {
            const dayNum = parseInt(d);
            // Count how many years have entries
            const count = Object.keys(db[key]).length;
            if (count > 0) {
                result[dayNum] = count;
            }
        }
    });

    return result;
};

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, TreeIcon } from './Icons';
import * as storageService from '../services/storageService';

interface CalendarViewProps {
  onSelectDate: (date: Date) => void;
  initialDate: Date;
}

const CalendarView: React.FC<CalendarViewProps> = ({ onSelectDate, initialDate }) => {
  const [currentMonth, setCurrentMonth] = useState(initialDate.getMonth());
  // Counts map: Day -> Number of entries
  const [counts, setCounts] = useState<Record<number, number>>({});

  useEffect(() => {
    // Month is 0-indexed in JS Date, but 1-indexed in our storage
    const data = storageService.getEntryCountsForMonth(currentMonth + 1);
    setCounts(data);
  }, [currentMonth]);

  const daysInMonth = new Date(2024, currentMonth + 1, 0).getDate(); // Using leap year 2024 to allow 29 days in Feb generally
  const monthName = new Date(2024, currentMonth).toLocaleString('en-US', { month: 'long' });

  const handleMonthChange = (delta: number) => {
    let newMonth = currentMonth + delta;
    if (newMonth > 11) newMonth = 0;
    if (newMonth < 0) newMonth = 11;
    setCurrentMonth(newMonth);
  };

  const handleDayClick = (day: number) => {
    const newDate = new Date();
    newDate.setMonth(currentMonth);
    newDate.setDate(day);
    onSelectDate(newDate);
  };

  return (
    <div className="flex flex-col h-full bg-paper pt-6">
      {/* Month Navigator */}
      <div className="flex items-center justify-between px-8 mb-8">
        <button 
          onClick={() => handleMonthChange(-1)}
          className="p-2 rounded-full hover:bg-white text-stone-400 hover:text-ink transition-colors"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
        <h2 className="font-serif text-3xl text-ink font-medium tracking-wide">
          {monthName}
        </h2>
        <button 
          onClick={() => handleMonthChange(1)}
          className="p-2 rounded-full hover:bg-white text-stone-400 hover:text-ink transition-colors"
        >
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>

      {/* Grid */}
      <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-20">
        <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-7 gap-3 max-w-3xl mx-auto">
          {Array.from({ length: daysInMonth }, (_, i) => i + 1).map((day) => {
            const count = counts[day] || 0;
            return (
              <button
                key={day}
                onClick={() => handleDayClick(day)}
                className={`
                  aspect-square rounded-2xl border flex flex-col items-center justify-between p-2 transition-all duration-300
                  ${count > 0 
                    ? 'bg-white border-accent/30 hover:shadow-md hover:border-accent' 
                    : 'bg-transparent border-stone-200/50 hover:bg-stone-50'
                  }
                `}
              >
                <span className={`text-sm font-serif ${count > 0 ? 'text-ink font-bold' : 'text-stone-300'}`}>
                  {day}
                </span>

                <div className="flex-1 flex items-center justify-center w-full flex-wrap content-center gap-0.5">
                  {count === 0 ? (
                      <div className="w-1 h-1 rounded-full bg-stone-200" />
                  ) : (
                      // Render trees up to a max (e.g., 5) to prevent overflow
                      Array.from({ length: Math.min(count, 5) }).map((_, idx) => (
                        <TreeIcon 
                            key={idx} 
                            className={`
                                text-accent 
                                ${count === 1 ? 'w-8 h-8' : ''}
                                ${count === 2 ? 'w-5 h-5' : ''}
                                ${count >= 3 ? 'w-3.5 h-3.5' : ''}
                            `} 
                        />
                      ))
                  )}
                  {count > 5 && (
                      <span className="text-[8px] text-accent font-bold leading-none">+</span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect, useMemo } from 'react';
import DateNavigator from './components/DateNavigator';
import EntryCard from './components/EntryCard';
import CalendarView from './components/CalendarView';
import { Sparkles, PlusIcon, CalendarIcon, ListIcon } from './components/Icons';
import * as storageService from './services/storageService';
import * as geminiService from './services/geminiService';
import { DiaryEntry } from './types';

const App: React.FC = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [viewMode, setViewMode] = useState<'timeline' | 'calendar'>('timeline');
  const [entries, setEntries] = useState<DiaryEntry[]>([]);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  const [isGenerating, setIsGenerating] = useState(false);
  const [insight, setInsight] = useState<string | null>(null);

  const dayMonth = useMemo(() => {
    const m = (currentDate.getMonth() + 1).toString().padStart(2, '0');
    const d = currentDate.getDate().toString().padStart(2, '0');
    return `${m}-${d}`;
  }, [currentDate]);

  // Load entries for current day
  useEffect(() => {
    if (viewMode === 'timeline') {
        const loaded = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
        setEntries(loaded);
        setInsight(null);
    }
  }, [currentDate, refreshTrigger, viewMode]);

  const handleUpdate = () => {
    setRefreshTrigger(prev => prev + 1);
  };

  const handleManualDelete = (yearToDelete: number) => {
     setEntries(prev => prev.filter(e => e.year !== yearToDelete));
     handleUpdate();
  };

  const handleAddEntry = () => {
    const currentYear = new Date().getFullYear();
    const existingYears = new Set(entries.map(e => e.year));

    let suggestedYear = currentYear;
    while (existingYears.has(suggestedYear)) {
        suggestedYear--;
    }

    const newEntry: DiaryEntry = {
        id: crypto.randomUUID(),
        dayMonth,
        year: suggestedYear,
        content: '',
        lastEdited: 0
    };

    setEntries(prev => [newEntry, ...prev].sort((a, b) => b.year - a.year));
  };

  const generateInsight = async () => {
    setIsGenerating(true);
    try {
      const currentEntries = storageService.getEntriesForDay(currentDate.getMonth() + 1, currentDate.getDate());
      const result = await geminiService.generateTimeCapsuleInsight(dayMonth, currentEntries);
      setInsight(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="h-screen flex flex-col bg-paper relative">

      {/* View Switcher Button */}
      <div className="fixed top-6 right-4 z-50">
        <button 
            onClick={() => setViewMode(prev => prev === 'timeline' ? 'calendar' : 'timeline')}
            className="bg-white/80 backdrop-blur-md p-3 rounded-full shadow-sm hover:shadow-md border border-stone-200 text-stone-500 hover:text-accent transition-all"
            title={viewMode === 'timeline' ? "View Calendar" : "View Timeline"}
        >
            {viewMode === 'timeline' ? <CalendarIcon className="w-5 h-5" /> : <ListIcon className="w-5 h-5" />}
        </button>
      </div>

      {viewMode === 'timeline' ? (
        <>
            <DateNavigator currentDate={currentDate} onDateChange={setCurrentDate} />

            <div className="flex-1 overflow-y-auto no-scrollbar pb-32">
                <main className="max-w-2xl mx-auto px-4 w-full flex flex-col gap-6 pt-4">

                <div className="flex justify-between items-center px-1 mb-2">
                    <h2 className="text-sm font-serif text-stone-400 italic">Timeline</h2>
                </div>

                {entries.length === 0 ? (
                    <div className="text-center py-20 opacity-40">
                        <p className="font-serif text-xl mb-2">No memories yet.</p>
                        <p className="text-sm">Click the + button to start a ring.</p>
                    </div>
                ) : (
                    entries.map((entry) => (
                        <EntryCard
                            key={`${dayMonth}-${entry.year}-${entry.id}`}
                            dayMonth={dayMonth}
                            initialData={entry}
                            onUpdate={handleUpdate}
                            onDelete={handleManualDelete}
                        />
                    ))
                )}

                {/* AI Insight Section */}
                <div className="mt-4 mb-8">
                    {insight ? (
                    <div className="bg-gradient-to-br from-stone-50 to-stone-100 rounded-2xl p-6 border border-stone-200 shadow-inner relative overflow-hidden animate-in fade-in duration-700">
                        <div className="absolute top-0 right-0 p-4 opacity-10">
                        <Sparkles className="w-24 h-24 text-accent" />
                        </div>
                        <h3 className="font-serif text-xl font-medium text-accent mb-3 flex items-center gap-2">
                            <Sparkles className="w-5 h-5" />
                            Time Patterns
                        </h3>
                        <p className="text-stone-600 leading-relaxed font-serif whitespace-pre-wrap">{insight}</p>
                        <button onClick={() => setInsight(null)} className="mt-4 text-xs text-stone-400 hover:text-stone-600">Close</button>
                    </div>
                    ) : (
                        entries.filter(e => e.content.length > 5).length >= 2 && (
                            <div className="flex justify-center">
                                <button
                                    onClick={generateInsight}
                                    disabled={isGenerating}
                                    className={`
                                        group relative overflow-hidden
                                        bg-white hover:bg-stone-50
                                        border border-stone-200 text-stone-500 hover:text-accent
                                        px-6 py-3 rounded-full shadow-sm
                                        transition-all duration-300
                                        flex items-center gap-2 text-sm font-medium tracking-wide
                                        ${isGenerating ? 'opacity-70 cursor-wait' : ''}
                                    `}
                                >
                                    <Sparkles className={`w-4 h-4 ${isGenerating ? 'animate-pulse' : 'group-hover:rotate-12 transition-transform'}`} />
                                    {isGenerating ? 'Connecting dots...' : 'Find patterns across years'}
                                </button>
                            </div>
                        )
                    )}
                </div>
                </main>
            </div>

            {/* Floating Action Button */}
            <div className="absolute bottom-8 right-6 md:right-1/4 z-20">
                <button
                    onClick={handleAddEntry}
                    className="bg-accent text-white p-4 rounded-full shadow-lg hover:bg-stone-600 hover:scale-110 active:scale-95 transition-all duration-300 flex items-center justify-center group"
                >
                    <PlusIcon className="w-8 h-8 group-hover:rotate-90 transition-transform" />
                </button>
            </div>

            {/* Decorative vertical line */}
            <div className="fixed top-0 bottom-0 left-1/2 -translate-x-1/2 w-px bg-stone-200 -z-0 hidden md:block pointer-events-none opacity-40"></div>
        </>
      ) : (
          <CalendarView 
            initialDate={currentDate} 
            onSelectDate={(date) => {
                setCurrentDate(date);
                setViewMode('timeline');
            }} 
          />
      )}

    </div>
  );
};

export default App;

