export const AnnualRingGraph: React.FC<{ count: number; className?: string }> = ({ count, className }) => {
  const cx = 12;
  const cy = 12;
  const effectiveCount = Math.min(count, 12); 

  // Pseudo-random function for deterministic organic texture
  const pseudoRandom = (seed: number) => {
    const x = Math.sin(seed) * 10000;
    return x - Math.floor(x);
  };

  const rings = [];
  const segments = 20; // High enough resolution for smooth-ish look

  // Track radius at each angle to ensure concentricity (prevent crossing)
  // Initialize with the pith radius
  const currentRadii = new Array(segments).fill(1.5); 

  // Calculate gap based on available space and count
  // Available radius space approx 10px (from 1.5 to 11.5)
  // If count is low, use a pleasing fixed gap. If high, condense.
  const avgGap = effectiveCount > 0 
    ? Math.min(2.5, 9 / effectiveCount) 
    : 2;

  for (let i = 0; i < effectiveCount; i++) {
    const points = [];

    for (let j = 0; j < segments; j++) {
      const angle = (j / segments) * Math.PI * 2;

      // Calculate growth for this segment
      // 1. Base gap
      // 2. Random variation (texture)
      // 3. Global shape distortion (makes the tree slightly oval or bumpy)

      const noise = (pseudoRandom(i * 100 + j) - 0.5) * (avgGap * 0.4);
      const shapeDistortion = Math.sin(angle * 2 + i * 0.2) * (avgGap * 0.2);

      const growth = Math.max(0.5, avgGap + noise + shapeDistortion); // Ensure at least some growth

      currentRadii[j] += growth;

      // Clamp to viewbox
      if (currentRadii[j] > 11.5) currentRadii[j] = 11.5;

      const r = currentRadii[j];
      const x = cx + r * Math.cos(angle);
      const y = cy + r * Math.sin(angle);
      points.push({x, y});
    }

    // Build SVG Path
    // Using linear segments is fine at this scale and adds to the "sketchy" look
    let d = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
    for (let k = 1; k < points.length; k++) {
      d += ` L ${points[k].x.toFixed(2)} ${points[k].y.toFixed(2)}`;
    }
    d += " Z"; // Close path

    rings.push(
      <path 
        key={i} 
        d={d}
        fill="none" 
        stroke="currentColor" 
        strokeWidth={0.6} // Fine pen width
        strokeLinecap="round"
        strokeLinejoin="round"
        className="opacity-90"
      />
    );
  }

  return (
    <svg viewBox="0 0 24 24" className={className}>
      {/* Pith (Center Heart) */}
      <circle cx={cx} cy={cy} r={1.2} fill="currentColor" className="opacity-100" />
      {rings}
    </svg>
  );
};

